import json, sys
for line in sys.stdin:
    try:
        obj = json.loads(line)
        role = obj.get('role', obj.get('type', ''))
        ts = obj.get('timestamp', '')
        content = obj.get('content', '')
        if isinstance(content, list):
            for c in content:
                t = c.get('type', '')
                if t == 'text':
                    print(f'[{ts}] [{role}] TEXT:', c.get('text', '')[:500])
                elif t == 'toolCall':
                    name = c.get('name', c.get('function', {}).get('name', ''))
                    args = c.get('arguments', c.get('function', {}).get('arguments', ''))
                    if isinstance(args, dict):
                        args = json.dumps(args, ensure_ascii=False)
                    print(f'[{ts}] [{role}] TOOL:', name, str(args)[:300])
                elif t == 'toolResult':
                    res = c.get('content', '')
                    if isinstance(res, list):
                        res = ' | '.join(str(x)[:200] for x in res)
                    print(f'[{ts}] [{role}] TOOL_RESULT:', str(res)[:500])
        else:
            print(f'[{ts}] [{role}]:', str(content)[:500])
    except Exception as e:
        print('ERR:', e)
" 2>&1 | head -80

python3 -c "
import json
with open('/home/halei/.openclaw/agents/tts/sessions/b6884754-e119-4101-a476-c467dbda5910.jsonl') as f:
    for line in f:
        obj = json.loads(line)
        t = obj.get('type', '')
        ts = obj.get('timestamp', '')
        if t == 'message':
            msg = obj.get('message', {})
            role = msg.get('role', '')
            content = msg.get('content', '')
            if isinstance(content, list):
                for c in content:
                    ct = c.get('type', '')
                    if ct == 'text':
                        txt = c.get('text', '')
                        print(f'[{ts}] [{role}] TEXT: {txt[:800]}')
                    elif ct == 'toolUse':
                        name = c.get('name', '')
                        inp = c.get('input', {})
                        print(f'[{ts}] [{role}] TOOL_USE: {name} | {json.dumps(inp, ensure_ascii=False)[:400]}')
                    elif ct == 'toolResult':
                        rc = c.get('content', '')
                        if isinstance(rc, list):
                            rc = ' || '.join(str(x)[:300] for x in rc)
                        print(f'[{ts}] [{role}] TOOL_RESULT: {str(rc)[:800]}')
            else:
                print(f'[{ts}] [{role}]: {str(content)[:400]}')
" 2>&1 | head -120

